'use client';
import { FormEvent, useEffect, useMemo, useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import SettingsPanel from './SettingsPanel';

type AnyRow = Record<string, any>;
type Line = { itemId:string; quantity:number };
const today=()=>new Date().toISOString().slice(0,10);
const escapeHtml=(value:any)=>String(value??'').replace(/[&<>"']/g,char=>char==='&'?'&amp;':char==='<'?'&lt;':char==='>'?'&gt;':char==='"'?'&quot;':'&#39;');
const displayDate=(value:string)=>value?new Date(value+'T00:00:00').toLocaleDateString('vi-VN'):'';

async function request(url:string,options?:RequestInit){
 const r=await fetch(url,{cache:'no-store',credentials:'same-origin',...options});
 const j=await r.json().catch(()=>({ok:false,error:`Máy chủ trả về mã lỗi ${r.status}.`}));
 if(!r.ok||!j.ok){const raw=j?.error;const message=typeof raw==='string'?raw:[raw?.message,raw?.details,raw?.hint].filter(Boolean).join(' — ');throw new Error(message||'Không thể xử lý yêu cầu. Vui lòng thử lại.');}
 return j.data
}
async function action(name:string,payload:AnyRow){return request('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:name,...payload})})}
async function uploadFile(file:File|null){if(!file)return '';const form=new FormData();form.set('file',file);const result=await request('/api/upload',{method:'POST',body:form});return result.path as string}

function SmartItemInput({items,value,onChange,stock=false}:{items:AnyRow[],value:string,onChange:(id:string)=>void,stock?:boolean}){
 const selectedLabel=useMemo(()=>{const row=items.find(x=>x.id===value);return row?`${row.code} - ${row.name}`:''},[items,value]);
 const [query,setQuery]=useState(selectedLabel);
 useEffect(()=>{setQuery(selectedLabel)},[selectedLabel]);
 const norm=(s:string)=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();
 const found=query.trim()?items.filter(x=>x.active&&norm(`${x.code} ${x.name} ${x.item_group||''}`).includes(norm(query))).slice(0,20):[];
 const handleInput=(text:string)=>{setQuery(text);if(value)onChange('')};
 return <div className="smart-select"><input value={query} onChange={e=>handleInput(e.target.value)} placeholder="Gõ mã hoặc tên mặt hàng" autoComplete="off"/>{query.trim()&&<div className="search-results">{found.length?found.map(x=>{const st=x.warehouse_stock?.[0]?.quantity;return <button type="button" className="search-item" style={{display:'block',width:'100%',textAlign:'left',background:'white',border:0}} key={x.id} onClick={()=>onChange(x.id)}>{x.code} - {x.name}{stock?` - Tồn ${st??0} ${x.unit}`:''}</button>}):<div className="search-item muted">Không tìm thấy mặt hàng phù hợp.</div>}</div>}</div>
}

function LinesEditor({items,lines,setLines,stock=false}:{items:AnyRow[],lines:Line[],setLines:(v:Line[])=>void,stock?:boolean}){const change=(i:number,key:keyof Line,value:any)=>setLines(lines.map((x,n)=>n===i?{...x,[key]:value}:x));return <><div className="table-wrap"><table><thead><tr><th>Mặt hàng</th><th>Số lượng</th><th>Thao tác</th></tr></thead><tbody>{lines.map((line,i)=><tr key={i}><td><SmartItemInput items={items} value={line.itemId} onChange={id=>change(i,'itemId',id)} stock={stock}/></td><td><input type="number" min="1" value={line.quantity} onChange={e=>change(i,'quantity',Number(e.target.value))}/></td><td><button type="button" className="btn danger" disabled={lines.length===1} onClick={()=>setLines(lines.filter((_,n)=>n!==i))}>Xóa</button></td></tr>)}</tbody></table></div><div className="actions"><button type="button" className="btn secondary" onClick={()=>setLines([...lines,{itemId:'',quantity:1}])}>＋ Thêm hàng</button></div></>}

export default function DashboardApp(){
 const router=useRouter();const [data,setData]=useState<AnyRow|null>(null);const [tab,setTab]=useState('overview');const [toast,setToast]=useState('');const [error,setError]=useState('');const [saving,setSaving]=useState(false);const [refreshing,setRefreshing]=useState(false);const [sidebarOpen,setSidebarOpen]=useState(false);const savingRef=useRef(false);const loadSeqRef=useRef(0);
 const load=async(background=false)=>{const seq=++loadSeqRef.current;const controller=new AbortController();const timeout=window.setTimeout(()=>controller.abort(),20000);if(background)setRefreshing(true);try{const fresh=await request('/api/data',{signal:controller.signal});if(seq===loadSeqRef.current){setData(fresh);setError('')}}catch(e:any){if(seq===loadSeqRef.current){const message=e?.name==='AbortError'?'Dữ liệu đã lưu nhưng đồng bộ nền quá thời gian. Hãy tải lại trang nếu cần.':e.message;setError(message);if(message.includes('hết hạn'))router.replace('/login')}}finally{window.clearTimeout(timeout);if(background&&seq===loadSeqRef.current)setRefreshing(false)}};
 useEffect(()=>{load()},[]);useEffect(()=>{document.body.classList.toggle('menu-open',sidebarOpen);const close=(e:KeyboardEvent)=>{if(e.key==='Escape')setSidebarOpen(false)};window.addEventListener('keydown',close);return()=>{document.body.classList.remove('menu-open');window.removeEventListener('keydown',close)}},[sidebarOpen]);const notify=(m:string)=>{setToast(m);setTimeout(()=>setToast(''),3500)};
 const doAction=async(name:string,payload:AnyRow|(()=>Promise<AnyRow>))=>{
  if(savingRef.current)throw new Error('Dữ liệu đang được lưu, vui lòng chờ hoàn tất.');
  savingRef.current=true;setSaving(true);
  try{setError('');const prepared=typeof payload==='function'?await payload():payload;const result=await action(name,prepared);notify('Đã lưu thành công.');void load(true);return result}
  catch(e:any){setError(e.message);throw e}
  finally{savingRef.current=false;setSaving(false)}
 };
 if(!data)return <main className="login-page"><div className="login-card"><h2>{error||'Đang tải dữ liệu...'}</h2></div></main>;
 const settings=Object.fromEntries((data.settings||[]).map((x:AnyRow)=>[x.key,x.value]));
 const menus=[['overview','🏠 Tổng quan'],['issue','📤 Tiếp nhận + cấp phát'],['collection','📥 Thu gom - ra viện'],['warehouse','📦 Kho đồ vải - vật tư'],['inventory','🧮 Kiểm kê khoa'],['losses','⚠️ Mất đồ'],['tracking','📌 Theo dõi'],['reports','🔒 Báo cáo'],['settings','🔒 Cài đặt']];
 async function logout(){await request('/api/auth/logout',{method:'POST'});router.replace('/login')}
 return <div className="shell">
  <button type="button" className={`sidebar-backdrop ${sidebarOpen?'show':''}`} aria-label="Đóng menu" onClick={()=>setSidebarOpen(false)}/>
  <aside className={`sidebar ${sidebarOpen?'open':''}`} aria-label="Menu chức năng">
   <div className="sidebar-head"><div className="brand">QUẢN LÝ ĐỒ VẢI</div><button type="button" className="sidebar-close" aria-label="Đóng menu" onClick={()=>setSidebarOpen(false)}>✕</button></div>
   <nav className="nav">{menus.map(m=><button key={m[0]} className={tab===m[0]?'active':''} onClick={()=>{if((m[0]==='reports'||m[0]==='settings')&&data.session.role!=='ADMIN'){setError('Chỉ người quản lý được mở mục này.');return}setTab(m[0]);setError('');setSidebarOpen(false)}}>{m[1]}</button>)}</nav>
  </aside>
  <main className="main">
   <header className="topbar app-header"><div className="header-title"><button type="button" className="menu-toggle" aria-label="Mở menu" aria-expanded={sidebarOpen} onClick={()=>setSidebarOpen(true)}>☰</button><div><h1>{settings.APP_TITLE}</h1><div className="muted">{settings.HOSPITAL_NAME} · {settings.DEPARTMENT_NAME}</div></div></div><div className="user-area"><strong>{data.session.fullName}</strong><span>·</span><button className="btn secondary" onClick={logout}>Đăng xuất</button></div></header>{error&&<div className="alert error">{error}</div>}
 {saving&&<div className="saving-overlay" role="status" aria-live="assertive"><div className="saving-box"><span className="saving-spinner" aria-hidden="true"/><strong>Đang lưu dữ liệu…</strong><span>Hệ thống đang cập nhật, vui lòng không bấm lại.</span></div></div>}{refreshing&&<div className="sync-status" role="status" aria-live="polite">Đã lưu · đang đồng bộ dữ liệu nền…</div>}
 {tab==='overview'&&<Overview data={data}/>} {tab==='issue'&&<Issue data={data} save={doAction}/>} {tab==='collection'&&<Collection data={data} save={doAction}/>} {tab==='warehouse'&&<Warehouse data={data} save={doAction}/>} {tab==='inventory'&&<Inventory data={data} save={doAction}/>} {tab==='losses'&&<Losses data={data} save={doAction}/>} {tab==='tracking'&&<Tracking data={data}/>} {tab==='reports'&&<Reports data={data}/>} {tab==='settings'&&<SettingsPanel data={data} save={doAction}/>} {toast&&<div className="toast">{toast}</div>}<footer className="app-footer">Tận tâm – Tận tình – Nâng tầm chất lượng <span>Phạm Văn Tú</span></footer>
  </main>
 </div>
}

function Overview({data}:{data:AnyRow}){
 const day=today(),active=data.patients.filter((p:AnyRow)=>p.status==='ACTIVE');
 const issueToday=data.issues.filter((x:AnyRow)=>x.issue_date===day);
 const collectToday=data.collections.filter((x:AnyRow)=>x.collection_date===day);
 const admitted=data.patients.filter((x:AnyRow)=>x.admission_date===day).length;
 const discharged=data.patients.filter((x:AnyRow)=>x.discharge_date===day).length;
 const issuedLinen=issueToday.reduce((sum:number,s:AnyRow)=>sum+s.issue_items.filter((i:AnyRow)=>i.catalog_items?.item_type==='LINEN').reduce((a:number,i:AnyRow)=>a+Number(i.quantity),0),0);
 const issuedSupply=issueToday.reduce((sum:number,s:AnyRow)=>sum+s.issue_items.filter((i:AnyRow)=>i.catalog_items?.item_type==='SUPPLY').reduce((a:number,i:AnyRow)=>a+Number(i.quantity),0),0);
 const collected=collectToday.reduce((sum:number,s:AnyRow)=>sum+s.collection_items.reduce((a:number,i:AnyRow)=>a+Number(i.returned_qty),0),0);
 const losses=data.losses.filter((x:AnyRow)=>x.loss_date===day).reduce((a:number,x:AnyRow)=>a+Number(x.quantity),0);
 const cards=[['Bệnh nhân hiện tại',active.length],['Vào viện hôm nay',admitted],['Ra viện hôm nay',discharged],['Đồ vải đã cấp',issuedLinen],['Đồ vải đã thu',collected],['Vật tư đã cấp',issuedSupply],['Thiếu/mất hôm nay',losses]];
 const byDept=data.departments.filter((d:AnyRow)=>d.active).map((d:AnyRow)=>{const ps=active.filter((p:AnyRow)=>p.department_id===d.id);const expected=ps.reduce((sum:number,p:AnyRow)=>sum+borrowedFor(data,p.id).reduce((a:number,x:any)=>a+Number(x.borrowedQty),0),0);return {...d,patients:ps.length,expected}});
 return <><h2>TỔNG QUAN HÔM NAY</h2><div className="grid kpis">{cards.map(x=><div className="kpi" key={x[0]}><strong>{x[1]}</strong><span>{x[0]}</span></div>)}</div><section className="card section-gap"><h2>Tổng hợp theo khoa</h2><div className="table-wrap"><table><thead><tr><th>Mã khoa</th><th>Khoa</th><th>Bệnh nhân đang điều trị</th><th>Đồ đang ở bệnh nhân</th></tr></thead><tbody>{byDept.map((x:AnyRow)=><tr key={x.id}><td>{x.code}</td><td>{x.name}</td><td>{x.patients}</td><td>{x.expected}</td></tr>)}</tbody></table></div></section></>}

function Issue({data,save}:{data:AnyRow,save:Function}){
 const [search,setSearch]=useState('');const [selected,setSelected]=useState<AnyRow|null>(null);const [image,setImage]=useState<File|null>(null);const [lines,setLines]=useState<Line[]>([{itemId:'',quantity:1}]);
 const active=data.patients.filter((p:AnyRow)=>p.status==='ACTIVE');
 const found=search.trim()?active.filter((p:AnyRow)=>(p.medical_code+' '+p.full_name+' '+p.departments?.name).toLowerCase().includes(search.toLowerCase())).slice(0,20):[];
 const oldBorrowed=selected?borrowedFor(data,selected.id):[];
 const applyPackage=(id:string)=>{const rows=data.packageItems.filter((x:AnyRow)=>x.package_id===id&&x.active).map((x:AnyRow)=>({itemId:x.item_id,quantity:Number(x.quantity)}));if(rows.length)setLines(rows)};
 const choose=(p:AnyRow)=>{setSelected(p);setSearch('');setLines([{itemId:'',quantity:1}])};
 async function submit(e:FormEvent<HTMLFormElement>){
  e.preventDefault();const form=e.currentTarget;const f=new FormData(form);const submitter=(e.nativeEvent as SubmitEvent).submitter as HTMLButtonElement|null;
  const common={patientId:selected?.id,medicalCode:f.get('medicalCode'),fullName:f.get('fullName'),gender:f.get('gender'),departmentId:f.get('departmentId'),departmentName:data.departments.find((x:AnyRow)=>x.id===f.get('departmentId'))?.name,admissionDate:f.get('admissionDate'),patientNote:f.get('patientNote')};
  if(submitter?.value==='updatePatient'){
   if(!selected)throw new Error('Hãy tìm và chọn bệnh nhân cần sửa.');
   await save('updatePatient',common);setSelected({...selected,medical_code:f.get('medicalCode'),full_name:f.get('fullName'),gender:f.get('gender'),department_id:f.get('departmentId'),admission_date:f.get('admissionDate'),departments:{name:data.departments.find((x:AnyRow)=>x.id===f.get('departmentId'))?.name}});return;
  }
  await save('saveIssue',async()=>{const imageUrl=await uploadFile(image);return {...common,issueDate:f.get('issueDate'),issuer:f.get('issuer'),receiver:f.get('receiver'),packageName:f.get('packageName'),note:f.get('note'),imageUrl,items:lines}});
  setLines([{itemId:'',quantity:1}]);setSelected(null);setSearch('');setImage(null);form.reset();
 }
 return <section className="card"><h2>TIẾP NHẬN BỆNH NHÂN + CẤP PHÁT ĐỒ</h2><label>Tìm bệnh nhân đang điều trị để cấp thêm hoặc sửa thông tin nhập viện<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Chỉ hiện kết quả sau khi gõ mã KCB, họ tên hoặc khoa"/></label>{found.length>0&&<div className="search-results">{found.map((p:AnyRow)=><div className="search-item" key={p.id} onClick={()=>choose(p)}>{p.medical_code} - {p.full_name} - {p.departments?.name}</div>)}</div>}{selected&&<div className="selected-patient"><strong>Đã chọn: {selected.medical_code} - {selected.full_name}</strong><span>Có thể sửa thông tin nhập viện hoặc cấp thêm vào phiếu cũ.</span></div>}<form className="section-gap" onSubmit={submit}><div className="form-grid"><div className="field third"><label>Mã bệnh nhân/Mã KCB<input name="medicalCode" required defaultValue={selected?.medical_code} key={'m'+selected?.id}/></label></div><div className="field third"><label>Họ và tên<input name="fullName" required defaultValue={selected?.full_name} key={'n'+selected?.id}/></label></div><div className="field third"><label>Giới tính<select name="gender" defaultValue={selected?.gender||'Nam'} key={'g'+selected?.id}><option>Nam</option><option>Nữ</option><option>Trẻ em</option></select></label></div><div className="field third"><label>Khoa điều trị<select name="departmentId" required defaultValue={selected?.department_id} key={'d'+selected?.id}><option value="">-- Chọn khoa --</option>{data.departments.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div><div className="field third"><label>Ngày vào viện<input name="admissionDate" type="date" defaultValue={selected?.admission_date||today()} key={'a'+selected?.id} required/></label></div><div className="field third"><label>Ngày cấp<input name="issueDate" type="date" defaultValue={today()} required/></label></div><div className="field third"><label>Nhân viên cấp<select name="issuer" required><option value="">-- Chọn --</option>{data.staff.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id}>{x.full_name}</option>)}</select></label></div><div className="field third"><label>Người nhận<input name="receiver"/></label></div><div className="field third"><label>Tên gói<input name="packageName" placeholder="Túi nam, Túi nữ..."/></label></div><div className="field full"><label>Ghi chú hồ sơ bệnh nhân<textarea name="patientNote" defaultValue={selected?.note||''} key={'pn'+selected?.id}/></label></div></div>{selected&&<section className="borrowed-box"><h3>Danh mục bệnh nhân đã mượn trong phiếu cũ</h3><div className="table-wrap"><table><thead><tr><th>Mã</th><th>Mặt hàng</th><th>Số lượng đang mượn</th><th>ĐVT</th></tr></thead><tbody>{oldBorrowed.length?oldBorrowed.map((r:any)=>{const item=data.items.find((x:AnyRow)=>x.id===r.itemId);return <tr key={r.itemId}><td>{item?.code}</td><td>{item?.name}</td><td><b>{r.borrowedQty}</b></td><td>{item?.unit}</td></tr>}):<tr><td colSpan={4}>Bệnh nhân chưa có đồ đang mượn.</td></tr>}</tbody></table></div></section>}<div className="actions">{data.packages.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><button type="button" className="btn secondary" key={x.id} onClick={()=>applyPackage(x.id)}>{x.name}</button>)}</div><h3>Danh sách đồ cấp phát thêm</h3><LinesEditor items={data.items.map((i:AnyRow)=>({...i,warehouse_stock:data.stock.filter((s:AnyRow)=>s.item_id===i.id)}))} lines={lines} setLines={setLines} stock/><label>Ảnh phiếu/chữ ký hai bên<input type="file" accept="image/*,application/pdf" onChange={e=>setImage(e.target.files?.[0]||null)}/></label><label>Ghi chú phiếu cấp<textarea name="note"/></label><div className="actions">{selected&&<button className="btn warning" name="intent" value="updatePatient" formNoValidate>Lưu sửa thông tin nhập viện</button>}<button className="btn success" name="intent" value="saveIssue">{selected?'Cấp thêm vào phiếu cũ':'Lưu tiếp nhận và cấp phát'}</button></div></form></section>
}

function rowTime(row:AnyRow,dateKey:string){
 const raw=row?.created_at||row?.[dateKey];
 if(!raw)return 0;
 const text=String(raw);
 return new Date(text.includes('T')?text:text+'T23:59:59').getTime();
}
function currentEpisodeCutoff(data:AnyRow,patientId:string){
 const completed=(data.collections||[]).filter((c:AnyRow)=>c.patient_id===patientId&&Boolean(c.discharged)).sort((a:AnyRow,b:AnyRow)=>rowTime(b,'collection_date')-rowTime(a,'collection_date'))[0];
 return completed?rowTime(completed,'collection_date'):null;
}
function borrowedFor(data:AnyRow,patientId:string){
 const cutoff=currentEpisodeCutoff(data,patientId);
 const result=new Map<string,number>();
 (data.issues||[]).filter((s:AnyRow)=>s.patient_id===patientId&&(cutoff===null||rowTime(s,'issue_date')>cutoff)).forEach((s:AnyRow)=>(s.issue_items||[]).forEach((x:AnyRow)=>result.set(x.item_id,(result.get(x.item_id)||0)+Number(x.quantity))));
 (data.collections||[]).filter((c:AnyRow)=>c.patient_id===patientId&&(cutoff===null||rowTime(c,'collection_date')>cutoff)).forEach((c:AnyRow)=>(c.collection_items||[]).forEach((x:AnyRow)=>result.set(x.item_id,(result.get(x.item_id)||0)-Number(x.returned_qty))));
 return [...result].filter(x=>x[1]>0).map(([itemId,qty])=>({itemId,borrowedQty:qty,returnedQty:qty}));
}
function Collection({data,save}:{data:AnyRow,save:Function}){
 const [mode,setMode]=useState<'detail'|'list'>('detail');
 const [search,setSearch]=useState('');
 const [patient,setPatient]=useState<AnyRow|null>(null);
 const [image,setImage]=useState<File|null>(null);
 const [rows,setRows]=useState<any[]>([]);
 const [lossReport,setLossReport]=useState<AnyRow|null>(null);
 const [listSearch,setListSearch]=useState('');
 const [quickDate,setQuickDate]=useState(today());
 const [quickCollector,setQuickCollector]=useState('');
 const [listDept,setListDept]=useState('');
 const [quickBusy,setQuickBusy]=useState('');
 const [quickError,setQuickError]=useState('');
 const active=data.patients.filter((p:AnyRow)=>p.status==='ACTIVE');
 const found=search.trim()?active.filter((p:AnyRow)=>(p.medical_code+' '+p.full_name+' '+p.departments?.name).toLowerCase().includes(search.toLowerCase())).slice(0,20):[];
 const listPatients=active.filter((p:AnyRow)=>(!listDept||p.department_id===listDept)&&(!listSearch.trim()||(p.medical_code+' '+p.full_name+' '+p.departments?.name).toLowerCase().includes(listSearch.toLowerCase())));
 const choose=(p:AnyRow)=>{setPatient(p);setRows(borrowedFor(data,p.id));setSearch('');setLossReport(null)};
 const openDetail=(p:AnyRow)=>{choose(p);setMode('detail');window.setTimeout(()=>document.getElementById('collection-detail')?.scrollIntoView({behavior:'smooth',block:'start'}),0)};
 async function quickDischarge(p:AnyRow){
  if(!quickCollector){setQuickError('Hãy chọn nhân viên thu gom đồ vải trước khi ra viện.');return}
  if(!quickDate){setQuickError('Hãy chọn ngày ra viện.');return}
  setQuickBusy(p.id);setQuickError('');
  try{
   const items=borrowedFor(data,p.id).map((x:any)=>({...x,returnedQty:Number(x.borrowedQty)}));
   await save('collectDischarge',{patientId:p.id,medicalCode:p.medical_code,fullName:p.full_name,departmentName:p.departments?.name,date:quickDate,collector:quickCollector,deliverer:'',discharged:true,reason:'Đủ đồ',resolution:'Đã thu hồi đủ đồ',note:'Ra viện nhanh theo danh sách',imageUrl:'',items});
  }catch(error:any){setQuickError(error?.message||'Không thể cập nhật ra viện.')}finally{setQuickBusy('')}
 }
 async function submit(e:FormEvent<HTMLFormElement>){
  e.preventDefault();if(!patient)throw new Error('Chưa chọn bệnh nhân');
  const form=e.currentTarget;const f=new FormData(form);
  const result=await save('collectDischarge',async()=>{const imageUrl=await uploadFile(image);return {patientId:patient.id,medicalCode:patient.medical_code,fullName:patient.full_name,departmentName:patient.departments?.name,date:f.get('date'),collector:f.get('collector'),deliverer:f.get('deliverer'),discharged:f.get('discharged')==='on',reason:f.get('reason'),resolution:f.get('resolution'),note:f.get('note'),imageUrl,items:rows}});
  if(result?.lossCount>0)setLossReport({...result,items:rows.filter((x:any)=>Number(x.borrowedQty)-Number(x.returnedQty)>0).map((x:any)=>({...x,missingQty:Number(x.borrowedQty)-Number(x.returnedQty),item:data.items.find((i:AnyRow)=>i.id===x.itemId)}))});else setLossReport(null);
  setPatient(null);setRows([]);setImage(null);form.reset();
 }
 return <><section className="card"><div className="topbar"><h2>THU GOM – BỆNH NHÂN RA VIỆN</h2><div className="actions" style={{marginTop:0}}><button type="button" className={'btn '+(mode==='detail'?'primary':'secondary')} onClick={()=>setMode('detail')}>Thu gom chi tiết</button><button type="button" className={'btn '+(mode==='list'?'primary':'secondary')} onClick={()=>setMode('list')}>Ra viện theo danh sách</button></div></div>{mode==='list'?<div className="section-gap"><div className="form-grid"><div className="field third"><label>Ngày ra viện<input type="date" value={quickDate} onChange={e=>setQuickDate(e.target.value)}/></label></div><div className="field third"><label>Nhân viên thu gom đồ vải<select value={quickCollector} onChange={e=>setQuickCollector(e.target.value)}><option value="">-- Chọn nhân viên --</option>{data.staff.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id} value={x.full_name}>{x.full_name}</option>)}</select></label></div><div className="field third"><label>Khoa<select value={listDept} onChange={e=>setListDept(e.target.value)}><option value="">Tất cả khoa</option>{data.departments.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div><div className="field full"><label>Tìm trong danh sách bệnh nhân đang điều trị<input value={listSearch} onChange={e=>setListSearch(e.target.value)} placeholder="Gõ mã KCB, họ tên hoặc khoa"/></label></div></div>{quickError&&<div className="alert error">{quickError}</div>}<div className="table-wrap"><table><thead><tr><th>Mã KCB</th><th>Họ tên</th><th>Khoa</th><th>Ngày vào</th><th>Thao tác</th></tr></thead><tbody>{listPatients.length?listPatients.map((p:AnyRow)=><tr key={p.id}><td>{p.medical_code}</td><td><b>{p.full_name}</b></td><td>{p.departments?.name}</td><td>{displayDate(p.admission_date)}</td><td><div className="actions" style={{marginTop:0}}><button type="button" className="btn success" disabled={quickBusy===p.id} onClick={()=>quickDischarge(p)}>{quickBusy===p.id?'Đang lưu…':'Ra viện đủ đồ'}</button><button type="button" className="btn warning" disabled={Boolean(quickBusy)} onClick={()=>openDetail(p)}>Ra viện không đủ đồ</button></div></td></tr>):<tr><td colSpan={5}>Không có bệnh nhân đang điều trị phù hợp.</td></tr>}</tbody></table></div><div className="muted section-gap">“Ra viện đủ đồ” xác nhận nhanh và kết thúc điều trị. “Ra viện không đủ đồ” bắt buộc chuyển sang biểu mẫu chi tiết để nhập số lượng trả và thiếu/mất.</div></div>:<div id="collection-detail"><label>Tìm bệnh nhân<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Gõ mã KCB, họ tên hoặc khoa"/></label>{found.length>0&&<div className="search-results">{found.map((p:AnyRow)=><div className="search-item" key={p.id} onClick={()=>choose(p)}>{p.medical_code} - {p.full_name} - {p.departments?.name}</div>)}</div>}{patient&&<form className="section-gap" onSubmit={submit}><div className="alert warning">{patient.medical_code} - <b>{patient.full_name}</b> - {patient.departments?.name}</div><div className="form-grid"><div className="field third"><label>Ngày thu<input name="date" type="date" defaultValue={today()} required/></label></div><div className="field third"><label>Nhân viên thu<select name="collector" required><option value="">-- Chọn --</option>{data.staff.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id}>{x.full_name}</option>)}</select></label></div><div className="field third"><label>Người giao<input name="deliverer"/></label></div></div><div className="table-wrap"><table><thead><tr><th>Mặt hàng</th><th>Đang mượn</th><th>Đã trả</th><th>Thiếu</th></tr></thead><tbody>{rows.length?rows.map((r:any,i:number)=>{const item=data.items.find((x:AnyRow)=>x.id===r.itemId);return <tr key={r.itemId}><td>{item?.name}</td><td>{r.borrowedQty}</td><td><input type="number" min="0" max={r.borrowedQty} value={r.returnedQty} onChange={e=>setRows(rows.map((x:any,n:number)=>n===i?{...x,returnedQty:Number(e.target.value)}:x))}/></td><td>{Math.max(0,r.borrowedQty-r.returnedQty)}</td></tr>}):<tr><td colSpan={4}>Bệnh nhân không còn đồ vải đang mượn.</td></tr>}</tbody></table></div><div className="form-grid section-gap"><div className="field"><label>Lý do thiếu<input name="reason"/></label></div><div className="field"><label>Hướng xử lý<input name="resolution"/></label></div><div className="field full"><label><input style={{width:'auto'}} name="discharged" type="checkbox" defaultChecked/> Xác nhận bệnh nhân ra viện</label></div><div className="field full"><label>Ảnh phiếu thu gom/chữ ký<input type="file" accept="image/*,application/pdf" onChange={e=>setImage(e.target.files?.[0]||null)}/></label></div><div className="field full"><label>Ghi chú<textarea name="note"/></label></div></div><div className="actions"><button type="button" className="btn secondary" onClick={()=>window.print()}>🖨 In phiếu thu gom</button><button className="btn success">Lưu thu gom và cập nhật ra viện</button></div></form>}</div>}</section>{lossReport&&<section className="card section-gap"><div className="alert warning"><strong>Đã tự động ghi {lossReport.lossCount} dòng mất đồ.</strong> Biên bản thiếu đồ đã sẵn sàng để in.</div><div className="actions"><button type="button" className="btn success" onClick={()=>printMissingReport(lossReport)}>🖨 Mở/In biên bản thiếu đồ</button></div></section>}</>
}
function Warehouse({data,save}:{data:AnyRow,save:Function}){
 const [receipt,setReceipt]=useState<Line[]>([{itemId:'',quantity:1}]);const [emergency,setEmergency]=useState<Line[]>([{itemId:'',quantity:1}]);const [patientSearch,setPatientSearch]=useState('');const [emergencyPatientId,setEmergencyPatientId]=useState('');
 const active=data.patients.filter((x:AnyRow)=>x.status==='ACTIVE');const selectedPatient=active.find((x:AnyRow)=>x.id===emergencyPatientId);const patientResults=patientSearch.trim()?active.filter((x:AnyRow)=>String(x.medical_code+' '+x.full_name+' '+x.departments?.name).toLowerCase().includes(patientSearch.toLowerCase())).slice(0,20):[];
 async function submitReceipt(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await save('receiveStock',{date:f.get('date'),performedBy:f.get('performedBy'),note:f.get('note'),items:receipt});setReceipt([{itemId:'',quantity:1}]);e.currentTarget.reset()}
 async function submitEmergency(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!emergencyPatientId)throw new Error('Hãy gõ và chọn đúng bệnh nhân đang điều trị.');const f=new FormData(e.currentTarget);await save('emergencyIssue',{date:f.get('date'),patientId:emergencyPatientId,performedBy:f.get('performedBy'),note:f.get('note'),items:emergency});setEmergency([{itemId:'',quantity:1}]);setEmergencyPatientId('');setPatientSearch('');e.currentTarget.reset()}
 return <><div className="grid two"><form className="card" onSubmit={submitReceipt}><h2>Nhập đồ vải/vật tư vào kho</h2><div className="form-grid"><div className="field"><label>Ngày nhập<input name="date" type="date" defaultValue={today()} required/></label></div><div className="field"><label>Người nhập<select name="performedBy" required><option value="">-- Chọn --</option>{data.staff.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id}>{x.full_name}</option>)}</select></label></div></div><LinesEditor items={data.items} lines={receipt} setLines={setReceipt}/><label>Ghi chú/nguồn nhập<input name="note"/></label><div className="actions"><button className="btn success">Nhập toàn bộ vào kho</button></div></form><form className="card" onSubmit={submitEmergency}><h2>Cấp/đổi đồ đơn lẻ – đột xuất</h2><div className="form-grid"><div className="field"><label>Ngày cấp<input name="date" type="date" defaultValue={today()} required/></label></div><div className="field"><label>Nhân viên cấp<select name="performedBy" required><option value="">-- Chọn --</option>{data.staff.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id}>{x.full_name}</option>)}</select></label></div><div className="field full"><label>Tìm và chọn bệnh nhân<input value={patientSearch} onChange={e=>{setPatientSearch(e.target.value);setEmergencyPatientId('')}} placeholder="Gõ mã KCB, họ tên hoặc khoa điều trị"/></label>{patientResults.length>0&&<div className="search-results">{patientResults.map((x:AnyRow)=><div className="search-item" key={x.id} onClick={()=>{setEmergencyPatientId(x.id);setPatientSearch('')}}>{x.medical_code} - {x.full_name} - {x.departments?.name}</div>)}</div>}{selectedPatient&&<div className="selected-patient"><strong>Đã chọn: {selectedPatient.medical_code} - {selectedPatient.full_name}</strong><span>{selectedPatient.departments?.name}</span></div>}<input type="hidden" name="patientId" value={emergencyPatientId}/></div></div><LinesEditor items={data.items.map((i:AnyRow)=>({...i,warehouse_stock:data.stock.filter((s:AnyRow)=>s.item_id===i.id)}))} lines={emergency} setLines={setEmergency} stock/><label>Lý do<input name="note" required/></label><div className="alert warning">Chỉ trừ tồn kho, không làm thay đổi phiếu mượn bệnh nhân.</div><div className="actions"><button className="btn warning">Cấp đồ đột xuất</button></div></form></div><section className="card section-gap"><h2>Số lượng tồn hiện tại</h2><div className="table-wrap"><table><thead><tr><th>Mã</th><th>Mặt hàng</th><th>Nhóm</th><th>Tồn</th><th>Mức cảnh báo</th><th>Trạng thái</th></tr></thead><tbody>{data.stock.map((x:AnyRow)=><tr key={x.item_id}><td>{x.catalog_items.code}</td><td>{x.catalog_items.name}</td><td>{x.catalog_items.item_type==='LINEN'?'Đồ vải':'Vật tư'}</td><td>{x.quantity} {x.catalog_items.unit}</td><td>{x.warning_level}</td><td><span className={'badge '+(Number(x.quantity)<=0?'red':Number(x.quantity)<=Number(x.warning_level)?'orange':'green')}>{Number(x.quantity)<=0?'HẾT - KHÔNG PHÁT':Number(x.quantity)<=Number(x.warning_level)?'SẮP HẾT':'ĐỦ PHÁT'}</span></td></tr>)}</tbody></table></div></section></>
}

function Inventory({data,save}:{data:AnyRow,save:Function}){
 const linens=data.items.filter((x:AnyRow)=>x.item_type==='LINEN'&&x.active);
 const [departmentId,setDepartmentId]=useState('__ALL__');
 const [itemId,setItemId]=useState('__ALL__');
 const [patientSearch,setPatientSearch]=useState('');
 const [selectedInventoryId,setSelectedInventoryId]=useState('');
 const [historyEdit,setHistoryEdit]=useState(false);
 const [historyValues,setHistoryValues]=useState<Record<string,{expected:number;actual:number}>>({});
 const active=data.patients.filter((p:AnyRow)=>p.status==='ACTIVE'&&(departmentId==='__ALL__'||p.department_id===departmentId));
 const detail=active.flatMap((p:AnyRow)=>borrowedFor(data,p.id).map((b:any)=>({patient:p,itemId:b.itemId,qty:b.borrowedQty}))).filter((x:any)=>data.items.find((i:AnyRow)=>i.id===x.itemId)?.item_type==='LINEN');
 const expected=new Map<string,number>();detail.forEach((x:any)=>expected.set(x.itemId,(expected.get(x.itemId)||0)+Number(x.qty)));
 const initial=linens.map((x:AnyRow)=>({itemId:x.id,expectedQty:expected.get(x.id)||0,actualQty:0}));
 const filteredInitial=itemId==='__ALL__'?initial:initial.filter((x:any)=>x.itemId===itemId);
 const normalizedSearch=patientSearch.trim().toLowerCase();
 const filteredDetail=(itemId==='__ALL__'?detail:detail.filter((x:any)=>x.itemId===itemId)).filter((x:any)=>!normalizedSearch||String(x.patient.medical_code+' '+x.patient.full_name).toLowerCase().includes(normalizedSearch));
 const [actual,setActual]=useState<Record<string,number>>({});
 const selectedInventory=(data.inventories||[]).find((x:AnyRow)=>x.id===selectedInventoryId);
 const valuesFor=(inventory:AnyRow)=>Object.fromEntries((inventory.inventory_items||[]).map((r:AnyRow)=>[r.id,{expected:Number(r.expected_qty),actual:Number(r.actual_qty)}]));
 function toggleInventory(inventory:AnyRow){if(selectedInventoryId===inventory.id){setSelectedInventoryId('');setHistoryEdit(false);return}setSelectedInventoryId(inventory.id);setHistoryValues(valuesFor(inventory));setHistoryEdit(false)}
 function resetHistory(){if(selectedInventory)setHistoryValues(valuesFor(selectedInventory));setHistoryEdit(false)}
 async function saveHistory(){if(!selectedInventory)return;await save('updateInventory',{inventoryId:selectedInventory.id,items:(selectedInventory.inventory_items||[]).map((r:AnyRow)=>({id:r.id,expectedQty:Number(historyValues[r.id]?.expected??r.expected_qty),actualQty:Number(historyValues[r.id]?.actual??r.actual_qty)}))});setHistoryEdit(false)}
 async function exportHistory(){if(!selectedInventory)return;const XLSX=await import('xlsx');const period=new Date(selectedInventory.inventory_time).toLocaleString('vi-VN');const summary=(selectedInventory.inventory_items||[]).map((r:AnyRow,i:number)=>{const item=r.catalog_items||data.items.find((x:AnyRow)=>x.id===r.item_id),v=historyValues[r.id]||{expected:Number(r.expected_qty),actual:Number(r.actual_qty)};return {STT:i+1,Mã:item?.code,'Mặt hàng':item?.name,'Dự kiến':v.expected,'Thực tế':v.actual,'Chênh lệch':v.actual-v.expected,ĐVT:item?.unit}});const patients=(selectedInventory.patient_items||[]).map((r:AnyRow,i:number)=>({STT:i+1,'Mã KCB':r.medicalCode,'Họ tên':r.fullName,Khoa:r.departmentName,'Mã mặt hàng':r.itemCode,'Mặt hàng':r.itemName,'Số lượng':r.quantity,ĐVT:r.unit}));const ws=XLSX.utils.aoa_to_sheet([['CHI TIẾT KIỂM KÊ'],['Thời gian',period],['Phạm vi',selectedInventory.scope==='HOSPITAL'?'TOÀN VIỆN':selectedInventory.departments?.name],[]]);XLSX.utils.sheet_add_json(ws,summary,{origin:'A5'});const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Chi tiết kiểm kê');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(patients),'Đồ tại từng bệnh nhân');XLSX.writeFile(wb,`Chi_tiet_kiem_ke_${String(selectedInventory.inventory_time).slice(0,10)}.xlsx`)}
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await save('saveInventory',{scope:departmentId==='__ALL__'?'HOSPITAL':'DEPARTMENT',departmentId:departmentId==='__ALL__'?null:departmentId,performedBy:f.get('performedBy'),note:f.get('note'),items:initial.map((x:any)=>({...x,actualQty:Number(actual[x.itemId]||0)})),patientItems:detail.map((x:any)=>{const item=data.items.find((r:AnyRow)=>r.id===x.itemId);return {patientId:x.patient.id,medicalCode:x.patient.medical_code,fullName:x.patient.full_name,departmentName:x.patient.departments?.name,itemId:x.itemId,itemCode:item?.code,itemName:item?.name,quantity:Number(x.qty),unit:item?.unit}})});setActual({})}
 async function excel(){const XLSX=await import('xlsx');const scope=departmentId==='__ALL__'?'TOÀN VIỆN':data.departments.find((x:AnyRow)=>x.id===departmentId)?.name;const summary=filteredInitial.map((r:any)=>{const item=linens.find((x:AnyRow)=>x.id===r.itemId),a=Number(actual[r.itemId]||0);return {Mã:item?.code,'Mặt hàng':item?.name,'Dự kiến đang có':r.expectedQty,'Thực tế kiểm kê':a,'Chênh lệch':a-r.expectedQty,ĐVT:item?.unit}});const patients=filteredDetail.map((x:any)=>{const item=data.items.find((r:AnyRow)=>r.id===x.itemId);return {'Mã KCB':x.patient.medical_code,'Họ tên bệnh nhân':x.patient.full_name,Khoa:x.patient.departments?.name,'Mã đồ':item?.code,'Đồ vải':item?.name,'Số lượng':x.qty,ĐVT:item?.unit}});const wb=XLSX.utils.book_new();const ws=XLSX.utils.json_to_sheet(summary);XLSX.utils.sheet_add_aoa(ws,[[`KIỂM KÊ ĐỒ HIỆN CÓ TẠI BỆNH NHÂN - ${scope}`],[`Ngày xuất: ${new Date().toLocaleString('vi-VN')}`],[]],{origin:'A1'});XLSX.utils.book_append_sheet(wb,ws,'Tổng hợp kiểm kê');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(patients),'Chi tiết từng bệnh nhân');XLSX.writeFile(wb,`Kiem_ke_do_tai_benh_nhan_${today()}.xlsx`)}
 return <><form className="card" onSubmit={submit}><div className="topbar"><div><h2>KIỂM KÊ ĐỒ HIỆN CÓ TẠI BỆNH NHÂN</h2><span className="muted">Bảng xuất Excel giữ đúng các cột: Mã, Mặt hàng, Dự kiến, Thực tế, Chênh lệch và ĐVT.</span></div><button type="button" className="btn success" onClick={excel}>Xuất Excel</button></div><div className="alert warning">Dự kiến được tính từ toàn bộ đồ đã cấp trừ đồ đã thu của bệnh nhân đang điều trị tại thời điểm mở kiểm kê.</div><div className="form-grid"><div className="field third"><label>Phạm vi<select value={departmentId} onChange={e=>{setDepartmentId(e.target.value);setActual({})}}><option value="__ALL__">TOÀN VIỆN</option>{data.departments.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div><div className="field third"><label>Số bệnh nhân<input value={active.length} readOnly/></label></div><div className="field third"><label>Người kiểm kê<select name="performedBy" required><option value="">-- Chọn nhân viên --</option>{data.staff.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id}>{x.full_name}</option>)}</select></label></div><div className="field full"><label>Lọc danh mục mặt hàng<select value={itemId} onChange={e=>setItemId(e.target.value)}><option value="__ALL__">TẤT CẢ MẶT HÀNG</option>{linens.map((x:AnyRow)=><option key={x.id} value={x.id}>{x.code} - {x.name}</option>)}</select></label></div></div><div className="table-wrap"><table><thead><tr><th>Mã</th><th>Mặt hàng</th><th>Dự kiến đang có</th><th>Thực tế kiểm kê</th><th>Chênh lệch</th><th>ĐVT</th></tr></thead><tbody>{filteredInitial.map((r:any)=>{const item=linens.find((x:AnyRow)=>x.id===r.itemId),a=Number(actual[r.itemId]||0);return <tr key={r.itemId}><td>{item?.code}</td><td>{item?.name}</td><td>{r.expectedQty}</td><td><input type="number" min="0" value={a} onChange={e=>setActual({...actual,[r.itemId]:Number(e.target.value)})}/></td><td><span className={'badge '+(a-r.expectedQty<0?'red':'green')}>{a-r.expectedQty}</span></td><td>{item?.unit}</td></tr>})}</tbody></table></div><label>Ghi chú<textarea name="note"/></label><div className="actions"><button className="btn success">Lưu kiểm kê và danh sách chi tiết</button></div></form><section className="card section-gap"><h2>Chi tiết đồ đang ở từng bệnh nhân</h2><label>Tìm bệnh nhân theo tên hoặc mã KCB<input value={patientSearch} onChange={e=>setPatientSearch(e.target.value)} placeholder="Gõ tên bệnh nhân hoặc mã KCB"/></label><div className="table-wrap section-gap"><table><thead><tr><th>Mã KCB</th><th>Họ tên</th><th>Khoa</th><th>Đồ vải</th><th>Số lượng</th><th>ĐVT</th></tr></thead><tbody>{filteredDetail.length?filteredDetail.map((x:any,i:number)=>{const item=data.items.find((r:AnyRow)=>r.id===x.itemId);return <tr key={i}><td>{x.patient.medical_code}</td><td>{x.patient.full_name}</td><td>{x.patient.departments?.name}</td><td>{item?.name}</td><td>{x.qty}</td><td>{item?.unit}</td></tr>}):<tr><td colSpan={6}>Không có đồ đang mượn theo bộ lọc đã chọn.</td></tr>}</tbody></table></div></section><section className="card section-gap"><h2>Lịch sử kiểm kê</h2><div className="alert warning">Bấm vào ngày kiểm kê để mở bảng chi tiết đã lưu tại thời điểm đó.</div><div className="table-wrap"><table><thead><tr><th>Thời gian</th><th>Khoa</th><th>Người kiểm kê</th><th>Số BN</th><th>Dự kiến</th><th>Thực tế</th><th>Chênh lệch</th></tr></thead><tbody>{(data.inventories||[]).length?(data.inventories||[]).map((x:AnyRow)=>{const expectedQty=(x.inventory_items||[]).reduce((a:number,r:AnyRow)=>a+Number(r.expected_qty),0),actualQty=(x.inventory_items||[]).reduce((a:number,r:AnyRow)=>a+Number(r.actual_qty),0);return <tr key={x.id} className={selectedInventoryId===x.id?'selected-row':''}><td><button type="button" className="link-button" onClick={()=>toggleInventory(x)}>{new Date(x.inventory_time).toLocaleString('vi-VN')}</button></td><td>{x.scope==='HOSPITAL'?'TOÀN VIỆN':x.departments?.name}</td><td>{x.performed_by}</td><td>{x.patient_count}</td><td>{expectedQty}</td><td>{actualQty}</td><td><span className={'badge '+(actualQty-expectedQty<0?'red':'green')}>{actualQty-expectedQty}</span></td></tr>}):<tr><td colSpan={7}>Chưa có dữ liệu kiểm kê.</td></tr>}</tbody></table></div>{selectedInventory&&<div className="history-detail"><div className="topbar"><h3>Chi tiết kiểm kê ngày {new Date(selectedInventory.inventory_time).toLocaleString('vi-VN')}</h3><div className="actions" style={{marginTop:0}}><button type="button" className="btn success" onClick={exportHistory}>Xuất Excel</button>{!historyEdit?<button type="button" className="btn warning" onClick={()=>setHistoryEdit(true)}>Sửa kiểm kê</button>:<><button type="button" className="btn secondary" onClick={resetHistory}>Hủy sửa</button><button type="button" className="btn success" onClick={saveHistory}>Lưu thay đổi</button></>}</div></div><div className="table-wrap"><table><thead><tr><th>Mã</th><th>Mặt hàng</th><th>Dự kiến</th><th>Thực tế</th><th>Chênh lệch</th><th>ĐVT</th></tr></thead><tbody>{(selectedInventory.inventory_items||[]).map((r:AnyRow)=>{const item=r.catalog_items||data.items.find((i:AnyRow)=>i.id===r.item_id),v=historyValues[r.id]||{expected:Number(r.expected_qty),actual:Number(r.actual_qty)};return <tr key={r.id}><td>{item?.code}</td><td>{item?.name}</td><td>{historyEdit?<input type="number" min="0" value={v.expected} onChange={e=>setHistoryValues({...historyValues,[r.id]:{...v,expected:Number(e.target.value)}})}/>:v.expected}</td><td>{historyEdit?<input type="number" min="0" value={v.actual} onChange={e=>setHistoryValues({...historyValues,[r.id]:{...v,actual:Number(e.target.value)}})}/>:v.actual}</td><td><span className={'badge '+(v.actual-v.expected<0?'red':'green')}>{v.actual-v.expected}</span></td><td>{item?.unit}</td></tr>})}</tbody></table></div><h3 className="section-gap">Danh sách đồ tại từng bệnh nhân đã lưu</h3><div className="table-wrap"><table><thead><tr><th>Mã KCB</th><th>Họ tên</th><th>Khoa</th><th>Mặt hàng</th><th>Số lượng</th><th>ĐVT</th></tr></thead><tbody>{(selectedInventory.patient_items||[]).length?(selectedInventory.patient_items||[]).map((r:AnyRow,i:number)=><tr key={i}><td>{r.medicalCode}</td><td>{r.fullName}</td><td>{r.departmentName}</td><td>{r.itemCode} - {r.itemName}</td><td>{r.quantity}</td><td>{r.unit}</td></tr>):<tr><td colSpan={6}>Lần kiểm kê cũ chưa có ảnh chụp chi tiết bệnh nhân.</td></tr>}</tbody></table></div></div>}</section></>
}

function Losses({data,save}:{data:AnyRow,save:Function}){
 const [patientQ,setPatientQ]=useState('');const [itemQ,setItemQ]=useState('');const [from,setFrom]=useState('');const [to,setTo]=useState('');const [open,setOpen]=useState(false);
 const invalidRange=Boolean(from&&to&&from>to);
 const rows=data.losses.filter((x:AnyRow)=>{const date=String(x.loss_date||''),patientText=String(x.patients?.medical_code+' '+x.patients?.full_name).toLowerCase(),itemText=String(x.catalog_items?.code+' '+x.catalog_items?.name).toLowerCase();return !invalidRange&&(!from||date>=from)&&(!to||date<=to)&&patientText.includes(patientQ.toLowerCase())&&itemText.includes(itemQ.toLowerCase())});
 const summaryMap=new Map<string,AnyRow>();
 rows.forEach((x:AnyRow)=>{const item=x.catalog_items||{},key=String(x.item_id||item.code||item.name),current=summaryMap.get(key)||{code:item.code||'',name:item.name||'Không xác định',unit:item.unit||'',quantity:0};current.quantity+=Number(x.quantity)||0;summaryMap.set(key,current)});
 const summaryRows=[...summaryMap.values()].sort((a:AnyRow,b:AnyRow)=>String(a.name).localeCompare(String(b.name),'vi'));
 const totalLost=summaryRows.reduce((sum:number,x:AnyRow)=>sum+Number(x.quantity),0);
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await save('saveLoss',{medicalCode:f.get('medicalCode'),itemId:f.get('itemId'),lossDate:f.get('lossDate'),quantity:Number(f.get('quantity')),reason:f.get('reason'),resolution:f.get('resolution'),recorder:f.get('recorder'),note:f.get('note')});e.currentTarget.reset();setOpen(false)}
 async function removeLoss(row:AnyRow){if(!window.confirm(`Hủy bản ghi mất ${row.quantity} ${row.catalog_items?.unit||''} ${row.catalog_items?.name||''} của ${row.patients?.full_name||'bệnh nhân'}?`))return;await save('deleteLoss',{lossId:row.id})}
 async function excel(){if(invalidRange){window.alert('Ngày bắt đầu không được lớn hơn ngày kết thúc.');return}if(!rows.length){window.alert('Không có dữ liệu trong khoảng đã chọn.');return}const XLSX=await import('xlsx');const period=`Từ ngày ${from?displayDate(from):'đầu kỳ'} đến ngày ${to?displayDate(to):'hiện tại'}`;const summarySheet=XLSX.utils.aoa_to_sheet([['TỔNG HỢP SỐ LƯỢNG MẤT ĐỒ'],[period],['Tổng số lượng mất',totalLost],[]]);XLSX.utils.sheet_add_json(summarySheet,summaryRows.map((x:AnyRow,i:number)=>({STT:i+1,'Mã mặt hàng':x.code,'Mặt hàng':x.name,'Tổng số lượng mất':x.quantity,'Đơn vị':x.unit})),{origin:'A5'});const detailSheet=XLSX.utils.aoa_to_sheet([['DANH SÁCH CHI TIẾT MẤT ĐỒ'],[period],[]]);XLSX.utils.sheet_add_json(detailSheet,rows.map((x:AnyRow,i:number)=>({STT:i+1,Ngày:displayDate(x.loss_date),'Mã KCB':x.patients?.medical_code,'Họ tên':x.patients?.full_name,'Mã mặt hàng':x.catalog_items?.code,'Mặt hàng':x.catalog_items?.name,'Số lượng':x.quantity,'Đơn vị':x.catalog_items?.unit,'Lý do':x.reason,'Xử lý':x.resolution})),{origin:'A4'});const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,summarySheet,'Tổng hợp mất đồ');XLSX.utils.book_append_sheet(wb,detailSheet,'Chi tiết mất đồ');XLSX.writeFile(wb,'Tong_hop_mat_do_'+(from||'dau')+'_'+(to||'nay')+'.xlsx')}
 function printList(){if(invalidRange){window.alert('Ngày bắt đầu không được lớn hơn ngày kết thúc.');return}if(!rows.length){window.alert('Không có dữ liệu trong khoảng đã chọn để in.');return}const body=rows.map((x:AnyRow,i:number)=>`<tr><td>${i+1}</td><td>${escapeHtml(displayDate(x.loss_date))}</td><td>${escapeHtml(x.patients?.medical_code)}</td><td>${escapeHtml(x.patients?.full_name)}</td><td>${escapeHtml(x.catalog_items?.name)}</td><td>${escapeHtml(x.quantity)} ${escapeHtml(x.catalog_items?.unit)}</td><td>${escapeHtml(x.reason)}</td><td>${escapeHtml(x.resolution)}</td></tr>`).join('');const summaryBody=summaryRows.map((x:AnyRow,i:number)=>`<tr><td>${i+1}</td><td>${escapeHtml(x.code)}</td><td>${escapeHtml(x.name)}</td><td>${escapeHtml(x.quantity)}</td><td>${escapeHtml(x.unit)}</td></tr>`).join('');const period=from||to?`Từ ngày ${from?displayDate(from):'đầu kỳ'} đến ngày ${to?displayDate(to):'hiện tại'}`:'Toàn bộ thời gian';const html=`<!doctype html><html><head><meta charset="utf-8"><title>Danh sách mất đồ</title><style>body{font-family:"Times New Roman",serif;margin:30px;color:#111}h1,h2,p{text-align:center;margin:4px}table{width:100%;border-collapse:collapse;margin-top:18px;font-size:13px}th,td{border:1px solid #000;padding:6px;text-align:left}th{background:#e9eef8}.meta{margin-top:12px;font-weight:bold}.sign{display:grid;grid-template-columns:1fr 1fr;text-align:center;margin-top:28px;font-weight:bold}@media print{button{display:none}}</style></head><body><h2>BỆNH VIỆN NGOẠI KHOA 115 NGHỆ AN</h2><h2>KHOA KIỂM SOÁT NHIỄM KHUẨN</h2><h1>DANH SÁCH MẤT ĐỒ</h1><p>${escapeHtml(period)}</p><div class="meta">Tổng số lượng mất: ${totalLost}</div><h2>TỔNG HỢP THEO MẶT HÀNG</h2><table><thead><tr><th>STT</th><th>Mã</th><th>Mặt hàng</th><th>Tổng mất</th><th>ĐVT</th></tr></thead><tbody>${summaryBody}</tbody></table><h2>CHI TIẾT MẤT ĐỒ</h2><table><thead><tr><th>STT</th><th>Ngày</th><th>Mã KCB</th><th>Họ tên</th><th>Mặt hàng</th><th>Số lượng</th><th>Lý do</th><th>Xử lý</th></tr></thead><tbody>${body}</tbody></table><div class="sign"><div>NGƯỜI LẬP DANH SÁCH<br><small>(Ký, ghi rõ họ tên)</small></div><div>TRƯỞNG KHOA KSNK<br><small>(Ký, ghi rõ họ tên)</small></div></div><script>window.onload=()=>window.print()<\/script></body></html>`;const w=window.open('','_blank');if(!w){window.alert('Trình duyệt đang chặn cửa sổ in.');return}w.document.write(html);w.document.close()}
 return <><section className="card"><div className="topbar"><h2>DANH SÁCH MẤT ĐỒ</h2><div><button type="button" className="btn secondary" onClick={()=>setOpen(!open)}>＋ Ghi nhận mất đồ</button> <button type="button" className="btn primary" onClick={printList}>🖨 In danh sách</button> <button type="button" className="btn success" onClick={excel}>Xuất Excel tổng hợp</button></div></div>{open&&<form className="section-gap" onSubmit={submit}><div className="form-grid"><div className="field third"><label>Ngày<input name="lossDate" type="date" defaultValue={today()} required/></label></div><div className="field third"><label>Mã KCB<input name="medicalCode"/></label></div><div className="field third"><label>Đồ vải<select name="itemId" required><option value="">-- Chọn đồ vải --</option>{data.items.filter((x:AnyRow)=>x.item_type==='LINEN'&&x.active).map((x:AnyRow)=><option key={x.id} value={x.id}>{x.code} - {x.name}</option>)}</select></label></div><div className="field third"><label>Số lượng<input name="quantity" type="number" min="1" defaultValue="1" required/></label></div><div className="field third"><label>Người ghi nhận<select name="recorder" required><option value="">-- Chọn nhân viên --</option>{data.staff.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id}>{x.full_name}</option>)}</select></label></div><div className="field"><label>Lý do<input name="reason"/></label></div><div className="field"><label>Hướng xử lý<input name="resolution"/></label></div><div className="field full"><label>Ghi chú<textarea name="note"/></label></div></div><div className="actions"><button className="btn success">Lưu mất đồ</button></div></form>}<div className="form-grid section-gap"><div className="field"><label>Từ ngày<input type="date" value={from} max={to||undefined} onChange={e=>setFrom(e.target.value)}/></label></div><div className="field"><label>Đến ngày<input type="date" value={to} min={from||undefined} onChange={e=>setTo(e.target.value)}/></label></div><div className="field"><label>Tìm bệnh nhân<input value={patientQ} onChange={e=>setPatientQ(e.target.value)} placeholder="Gõ mã KCB hoặc họ tên bệnh nhân"/></label></div><div className="field"><label>Tìm mặt hàng<input value={itemQ} onChange={e=>setItemQ(e.target.value)} placeholder="Gõ mã hoặc tên mặt hàng"/></label></div></div>{invalidRange&&<div className="alert error">Ngày bắt đầu không được lớn hơn ngày kết thúc.</div>}<div className="alert warning">Đang hiển thị <b>{rows.length}</b> bản ghi, tổng cộng <b>{totalLost}</b> đơn vị mất theo bộ lọc. Nút In và Xuất Excel chỉ lấy các dòng này.</div><section className="section-gap"><div className="topbar"><h3>TỔNG HỢP SỐ LƯỢNG MẤT THEO MẶT HÀNG</h3><span className="badge red">Tổng mất: {totalLost}</span></div><div className="table-wrap"><table><thead><tr><th>STT</th><th>Mã</th><th>Mặt hàng</th><th>Tổng số lượng mất</th><th>ĐVT</th></tr></thead><tbody>{summaryRows.length?summaryRows.map((x:AnyRow,i:number)=><tr key={x.code+'-'+x.name}><td>{i+1}</td><td>{x.code}</td><td>{x.name}</td><td><b>{x.quantity}</b></td><td>{x.unit}</td></tr>):<tr><td colSpan={5}>Không có dữ liệu tổng hợp trong khoảng ngày đã chọn.</td></tr>}</tbody></table></div></section><section className="section-gap"><h3>CHI TIẾT MẤT ĐỒ</h3><div className="table-wrap"><table><thead><tr><th>Ngày</th><th>Mã KCB</th><th>Họ tên</th><th>Mặt hàng</th><th>Số lượng</th><th>Lý do</th><th>Xử lý</th><th>Thao tác</th></tr></thead><tbody>{rows.length?rows.map((x:AnyRow)=><tr key={x.id}><td>{displayDate(x.loss_date)}</td><td>{x.patients?.medical_code}</td><td>{x.patients?.full_name}</td><td>{x.catalog_items?.name}</td><td>{x.quantity} {x.catalog_items?.unit}</td><td>{x.reason}</td><td>{x.resolution}</td><td><button type="button" className="btn danger" onClick={()=>removeLoss(x)}>Hủy/Xóa</button></td></tr>):<tr><td colSpan={8}>Không có dữ liệu trong khoảng ngày đã chọn.</td></tr>}</tbody></table></div></section></section></>
}

function printMissingReport(report:AnyRow){const rows=(report.items||[]).map((x:AnyRow,i:number)=>`<tr><td>${i+1}</td><td>${String(x.item?.name||'')}</td><td>${Number(x.missingQty)||0}</td><td>${String(x.item?.unit||'')}</td></tr>`).join('');const html=`<!doctype html><html><head><meta charset="utf-8"><title>Biên bản thiếu đồ vải</title><style>body{font-family:"Times New Roman",serif;margin:40px;font-size:17px}h1,h2,p{text-align:center;margin:3px}table{width:100%;border-collapse:collapse;margin:12px 0}th,td{border:1px solid #000;padding:5px}.sign{display:grid;grid-template-columns:repeat(3,1fr);text-align:center;font-weight:bold;margin-top:18px}.note{text-align:left}</style></head><body><h2>BỆNH VIỆN NGOẠI KHOA 115 NGHỆ AN</h2><h2>KHOA KIỂM SOÁT NHIỄM KHUẨN</h2><h1>BIÊN BẢN THIẾU ĐỒ VẢI</h1><p><i>Số phiếu thu gom: ${report.collectionNo||''}</i></p><div>Hôm nay, ngày ${report.date||''}, chúng tôi lập biên bản ghi nhận đồ vải còn thiếu khi thu gom/ra viện:</div><div>Họ tên người bệnh: <b>${report.patient?.fullName||''}</b></div><div>Mã người bệnh/Mã KCB: ${report.patient?.medicalCode||''}</div><div>Khoa điều trị: ${report.patient?.department||''}</div><table><thead><tr><th>STT</th><th>Tên đồ vải/vật tư</th><th>Số lượng thiếu</th><th>Đơn vị</th></tr></thead><tbody>${rows}</tbody></table><div>Lý do/ghi nhận: ${report.reason||'Chưa xác định.'}</div><div>Hướng xử lý: ${report.resolution||''}</div><div>Biên bản được lập để các bên xác nhận và làm căn cứ tổng hợp.</div><div class="sign"><div>ĐẠI DIỆN NGƯỜI BỆNH<br><small>(Ký, ghi rõ họ tên)</small></div><div>NHÂN VIÊN THU GOM<br><small>${report.collector||''}<br>(Ký, ghi rõ họ tên)</small></div><div>KẾ TOÁN XÁC NHẬN<br><small>(Ký, ghi rõ họ tên)</small></div></div><p style="margin-top:70px;color:#d22;font-weight:bold;font-style:italic">Tận tâm – Tận tình – Nâng tầm chất lượng</p><p style="text-align:right;font-style:italic">Phạm Văn Tú</p><script>window.onload=()=>window.print()<\/script></body></html>`;const w=window.open('','_blank');if(!w)throw new Error('Trình duyệt đang chặn cửa sổ in.');w.document.write(html);w.document.close()}

function Tracking({data}:{data:AnyRow}){
 const [from,setFrom]=useState(today()),[to,setTo]=useState(today()),[dept,setDept]=useState(''),[patientSearch,setPatientSearch]=useState('');
 const [statusFilter,setStatusFilter]=useState<'ALL'|'ADMITTED'|'DISCHARGED'>('ALL');
 const invalidRange=Boolean(from&&to&&from>to);
 const q=patientSearch.trim().toLowerCase();
 const matchesText=(p:AnyRow)=>String(p.medical_code+' '+p.full_name+' '+p.departments?.name).toLowerCase().includes(q);
 const inRange=(value:any)=>{const date=String(value||'').slice(0,10);return !invalidRange&&(!from||date>=from)&&(!to||date<=to)};
 const admittedRow=(p:AnyRow)=>inRange(p.admission_date);
 const dischargedRow=(p:AnyRow)=>Boolean(p.discharge_date)&&inRange(p.discharge_date);
 const allRows=data.patients.filter((p:AnyRow)=>(!dept||p.department_id===dept)&&(!q||matchesText(p))&&(admittedRow(p)||dischargedRow(p)));
 const rows=allRows.filter((p:AnyRow)=>statusFilter==='ALL'||(statusFilter==='ADMITTED'?admittedRow(p):dischargedRow(p)));
 const active=data.patients.filter((p:AnyRow)=>p.status==='ACTIVE'&&(!dept||p.department_id===dept)&&(!q||matchesText(p)));
 const admitted=rows.filter(admittedRow).length;
 const discharged=rows.filter(dischargedRow).length;
 async function exportExcel(){
  if(invalidRange){window.alert('Ngày bắt đầu không được lớn hơn ngày kết thúc.');return}
  if(!rows.length){window.alert('Không có bệnh nhân phù hợp bộ lọc để xuất Excel.');return}
  const XLSX=await import('xlsx');
  const filterLabel=statusFilter==='ADMITTED'?'Bệnh nhân nhập viện':statusFilter==='DISCHARGED'?'Bệnh nhân ra viện':'Tất cả bệnh nhân';
  const output=rows.map((p:AnyRow)=>({'Mã KCB':p.medical_code,'Họ tên':p.full_name,'Khoa':p.departments?.name||'','Ngày vào viện':p.admission_date||'','Ngày ra viện':p.discharge_date||'','Trạng thái':p.status==='ACTIVE'?'Đang điều trị':'Đã ra viện','Bộ lọc':filterLabel}));
  const ws=XLSX.utils.json_to_sheet(output);
  ws['!cols']=[{wch:18},{wch:28},{wch:28},{wch:15},{wch:15},{wch:18},{wch:24}];
  const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Theo dõi vào ra');
  XLSX.writeFile(wb,'theo-doi-benh-nhan-'+today()+'.xlsx');
 }
 return <><section className="card"><div className="topbar"><h2>THEO DÕI BỆNH NHÂN VÀO – RA</h2><button type="button" className="btn success" onClick={exportExcel}>Xuất Excel danh sách sau lọc</button></div><div className="form-grid"><div className="field third"><label>Từ ngày<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label></div><div className="field third"><label>Đến ngày<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></div><div className="field third"><label>Khoa<select value={dept} onChange={e=>setDept(e.target.value)}><option value="">Toàn viện</option>{data.departments.filter((x:AnyRow)=>x.active).map((x:AnyRow)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div><div className="field full"><label>Tìm bệnh nhân theo tên hoặc mã KCB<input value={patientSearch} onChange={e=>setPatientSearch(e.target.value)} placeholder="Gõ tên bệnh nhân hoặc mã số bệnh nhân"/></label></div></div><div className="actions filter-actions"><button type="button" className={'btn '+(statusFilter==='ALL'?'primary':'secondary')} onClick={()=>setStatusFilter('ALL')}>Tất cả</button><button type="button" className={'btn '+(statusFilter==='ADMITTED'?'primary':'secondary')} onClick={()=>setStatusFilter('ADMITTED')}>Lọc bệnh nhân nhập viện</button><button type="button" className={'btn '+(statusFilter==='DISCHARGED'?'primary':'secondary')} onClick={()=>setStatusFilter('DISCHARGED')}>Lọc bệnh nhân ra viện</button></div>{invalidRange&&<div className="alert error">Ngày bắt đầu không được lớn hơn ngày kết thúc.</div>}<div className="grid kpis section-gap"><div className="kpi"><strong>{active.length}</strong><span>Đang điều trị theo bộ lọc</span></div><div className="kpi"><strong>{admitted}</strong><span>Nhập viện theo bộ lọc</span></div><div className="kpi"><strong>{discharged}</strong><span>Ra viện theo bộ lọc</span></div></div><div className="muted section-gap">Đang hiển thị {rows.length} bệnh nhân · Bộ lọc: {statusFilter==='ADMITTED'?'Nhập viện':statusFilter==='DISCHARGED'?'Ra viện':'Tất cả'}</div><div className="table-wrap"><table><thead><tr><th>Mã KCB</th><th>Họ tên</th><th>Khoa</th><th>Ngày vào</th><th>Ngày ra</th><th>Trạng thái</th></tr></thead><tbody>{rows.length?rows.map((x:AnyRow)=><tr key={x.id}><td>{x.medical_code}</td><td>{x.full_name}</td><td>{x.departments?.name}</td><td>{displayDate(x.admission_date)}</td><td>{x.discharge_date?displayDate(x.discharge_date):'—'}</td><td><span className={'badge '+(x.status==='ACTIVE'?'green':'gray')}>{x.status==='ACTIVE'?'Đang điều trị':'Đã ra viện'}</span></td></tr>):<tr><td colSpan={6}>Không có bệnh nhân phù hợp bộ lọc.</td></tr>}</tbody></table></div></section></>
}
function Reports({data}:{data:AnyRow}){
 const monthStart=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`};
 const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
 const [from,setFrom]=useState(monthStart);const [to,setTo]=useState(localToday);
 const invalidRange=Boolean(from&&to&&from>to);
 const inRange=(value:any)=>{const date=String(value||'').slice(0,10);return !invalidRange&&(!from||date>=from)&&(!to||date<=to)};
 const setWeek=()=>{const end=new Date(),start=new Date(end);start.setDate(end.getDate()-((end.getDay()+6)%7));const ymd=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;setFrom(ymd(start));setTo(ymd(end))};
 const setMonth=()=>{setFrom(monthStart());setTo(localToday())};
 const issues=(data.issues||[]).filter((x:AnyRow)=>inRange(x.issue_date));
 const emergency=(data.transactions||[]).filter((x:AnyRow)=>x.transaction_type==='EMERGENCY_ISSUE'&&inRange(x.transaction_date));
 const summarize=(type:'LINEN'|'SUPPLY')=>{const map=new Map<string,AnyRow>();const add=(item:AnyRow,regular:number,urgent:number)=>{if(!item||item.item_type!==type)return;const key=String(item.id||item.code||item.name),old=map.get(key)||{code:item.code,name:item.name,unit:item.unit,regularQty:0,emergencyQty:0,totalQty:0};old.regularQty+=regular;old.emergencyQty+=urgent;old.totalQty+=regular+urgent;map.set(key,old)};issues.forEach((slip:AnyRow)=>(slip.issue_items||[]).forEach((line:AnyRow)=>add(line.catalog_items,Number(line.quantity)||0,0)));emergency.forEach((line:AnyRow)=>add(line.catalog_items,0,Number(line.out_qty)||0));return [...map.values()].sort((a:AnyRow,b:AnyRow)=>String(a.name).localeCompare(String(b.name),'vi'))};
 const linenRows=summarize('LINEN'),supplyRows=summarize('SUPPLY');
 const linenTotal=linenRows.reduce((sum:number,x:AnyRow)=>sum+x.totalQty,0),supplyTotal=supplyRows.reduce((sum:number,x:AnyRow)=>sum+x.totalQty,0);
 const transactions=(data.transactions||[]).filter((x:AnyRow)=>inRange(x.transaction_date));
 const SummaryTable=({title,rows,total}:{title:string,rows:AnyRow[],total:number})=><section className="card section-gap"><div className="topbar"><h2>{title}</h2><span className="badge green">Tổng: {total}</span></div><div className="table-wrap"><table><thead><tr><th>Mã</th><th>Mặt hàng</th><th>Cấp theo phiếu</th><th>Cấp đột xuất</th><th>Tổng cấp trong kỳ</th><th>ĐVT</th></tr></thead><tbody>{rows.length?rows.map((x:AnyRow)=><tr key={x.code+'-'+x.name}><td>{x.code}</td><td>{x.name}</td><td>{x.regularQty}</td><td>{x.emergencyQty}</td><td><b>{x.totalQty}</b></td><td>{x.unit}</td></tr>):<tr><td colSpan={6}>Không có dữ liệu cấp phát trong khoảng ngày đã chọn.</td></tr>}</tbody><tfoot><tr><th colSpan={4}>TỔNG CỘNG</th><th>{total}</th><th></th></tr></tfoot></table></div></section>;
 return <><section className="card"><div className="topbar"><div><h2>BÁO CÁO CẤP PHÁT THEO THỜI GIAN</h2><span className="muted">Theo dõi riêng đồ vải và vật tư theo tuần, tháng hoặc khoảng ngày tùy chọn.</span></div><div className="actions" style={{marginTop:0}}><button type="button" className="btn secondary" onClick={setWeek}>Tuần này</button><button type="button" className="btn primary" onClick={setMonth}>Tháng này</button></div></div><div className="form-grid"><div className="field"><label>Từ ngày<input type="date" value={from} max={to||undefined} onChange={e=>setFrom(e.target.value)}/></label></div><div className="field"><label>Đến ngày<input type="date" value={to} min={from||undefined} onChange={e=>setTo(e.target.value)}/></label></div></div>{invalidRange&&<div className="alert error">Ngày bắt đầu không được lớn hơn ngày kết thúc.</div>}<div className="grid kpis section-gap"><div className="kpi"><strong>{issues.length}</strong><span>Phiếu cấp trong kỳ</span></div><div className="kpi"><strong>{linenTotal}</strong><span>Tổng đồ vải đã cấp</span></div><div className="kpi"><strong>{supplyTotal}</strong><span>Tổng vật tư đã cấp</span></div><div className="kpi"><strong>{emergency.reduce((sum:number,x:AnyRow)=>sum+Number(x.out_qty||0),0)}</strong><span>Tổng cấp đột xuất</span></div></div></section><SummaryTable title="ĐỒ VẢI ĐÃ CẤP" rows={linenRows} total={linenTotal}/><SummaryTable title="VẬT TƯ ĐÃ CẤP" rows={supplyRows} total={supplyTotal}/><section className="card section-gap"><h2>Giao dịch kho trong kỳ</h2><div className="table-wrap"><table><thead><tr><th>Ngày</th><th>Loại</th><th>Mặt hàng</th><th>Nhập</th><th>Xuất</th><th>Tồn sau</th><th>Người thực hiện</th></tr></thead><tbody>{transactions.length?transactions.map((x:AnyRow)=><tr key={x.id}><td>{displayDate(x.transaction_date)}</td><td>{x.transaction_type}</td><td>{x.catalog_items?.name}</td><td>{x.in_qty}</td><td>{x.out_qty}</td><td>{x.balance_after}</td><td>{x.performed_by}</td></tr>):<tr><td colSpan={7}>Không có giao dịch kho trong khoảng ngày đã chọn.</td></tr>}</tbody></table></div></section></>
}

function Settings({data,save}:{data:AnyRow,save:Function}){async function settings(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await save('saveSettings',{rows:data.settings.map((x:AnyRow)=>({key:x.key,value:f.get(x.key),description:x.description}))})}async function catalog(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await save('saveCatalog',{item:{code:f.get('code'),name:f.get('name'),item_type:f.get('item_type'),item_group:f.get('item_group'),unit:f.get('unit'),default_qty:Number(f.get('default_qty')),collectable:f.get('collectable')==='on',active:true,sort_order:999}});e.currentTarget.reset()}async function password(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await save('changePassword',{password:f.get('password')});e.currentTarget.reset()}return <div className="grid two"><form className="card" onSubmit={settings}><h2>Thông tin chung</h2>{data.settings.map((x:AnyRow)=><label key={x.key}>{x.description}<input name={x.key} defaultValue={x.value}/></label>)}<div className="actions"><button className="btn success">Lưu cài đặt</button></div></form><div className="grid"><form className="card" onSubmit={catalog}><h2>Thêm/sửa đồ vải, vật tư</h2><div className="form-grid"><div className="field"><label>Mã<input name="code" required/></label></div><div className="field"><label>Tên<input name="name" required/></label></div><div className="field"><label>Loại<select name="item_type"><option value="LINEN">Đồ vải</option><option value="SUPPLY">Vật tư</option></select></label></div><div className="field"><label>Nhóm<input name="item_group"/></label></div><div className="field"><label>Đơn vị<input name="unit" defaultValue="cái"/></label></div><div className="field"><label>Số lượng mặc định<input name="default_qty" type="number" defaultValue="1"/></label></div><div className="field full"><label><input style={{width:'auto'}} name="collectable" type="checkbox" defaultChecked/> Thu gom khi ra viện</label></div></div><div className="actions"><button className="btn success">Lưu danh mục</button></div></form><form className="card" onSubmit={password}><h2>Đổi mật khẩu quản lý</h2><label>Mật khẩu mới<input name="password" type="password" minLength={8} required/></label><div className="actions"><button className="btn warning">Đổi mật khẩu</button></div></form></div></div>}
